# %% CELL 3: Full Neural Network Backbone
class FullIDSModel(nn.Module):
    """
    Full model before split. The split point will be generated automatically.
    Candidate cut k means client uses feature_layers[:k], server uses feature_layers[k:] + classifier.
    """
    def __init__(self, input_dim: int):
        super().__init__()
        self.feature_layers = nn.ModuleList([
            nn.Sequential(nn.Linear(input_dim, 128), nn.ReLU()),
            nn.Sequential(nn.Linear(128, 96), nn.ReLU()),
            nn.Sequential(nn.Linear(96, 64), nn.ReLU()),
            nn.Sequential(nn.Linear(64, 48), nn.ReLU()),
            nn.Sequential(nn.Linear(48, 32), nn.ReLU()),
            nn.Sequential(nn.Linear(32, 16), nn.ReLU()),
        ])
        self.classifier = nn.Sequential(
            nn.Linear(16, 1),
            nn.Sigmoid()
        )

    def forward(self, x):
        for layer in self.feature_layers:
            x = layer(x)
        return self.classifier(x)

input_dim = X_train_tensor.shape[1]
full_model_template = FullIDSModel(input_dim)
print(full_model_template)


# %% CELL 4: RAST Node Definition + Resource Profiler
@dataclass
class RASTNode:
    cut: int
    layer_name: str
    output_dim: int
    activation_bytes_per_batch: int
    communication_bytes_per_batch: int
    client_params: int
    server_params: int
    client_flops_per_sample: int
    server_flops_per_sample: int
    feasible: bool = True
    reason: str = "OK"


def count_params(module: nn.Module) -> int:
    return sum(p.numel() for p in module.parameters() if p.requires_grad)


def linear_flops(in_features: int, out_features: int) -> int:
    # Approx multiply-add cost. Simple estimate: 2 * in * out
    return 2 * in_features * out_features


def build_layer_dims(input_dim: int) -> List[Tuple[int, int]]:
    # (input_dim, output_dim) for each feature layer
    dims = [(input_dim, 128), (128, 96), (96, 64), (64, 48), (48, 32), (32, 16)]
    return dims


def construct_rast(input_dim: int, batch_size: int = 512) -> List[RASTNode]:
    """
    Resource-Aware Split Tree (RAST) for a sequential MLP.
    Each node represents a possible split after a feature layer.
    """
    dims = build_layer_dims(input_dim)
    total_flops = sum(linear_flops(i, o) for i, o in dims) + linear_flops(16, 1)

    nodes = []
    for cut in range(1, len(dims) + 1):
        out_dim = dims[cut - 1][1]
        activation_bytes = batch_size * out_dim * 4  # float32
        communication_bytes = 2 * activation_bytes  # forward activation + backward gradient

        client_flops = sum(linear_flops(i, o) for i, o in dims[:cut])
        server_flops = total_flops - client_flops

        # Parameter estimate by constructing temporary split modules
        full = FullIDSModel(input_dim)
        client_layers = nn.Sequential(*list(full.feature_layers[:cut]))
        server_layers = nn.Sequential(*list(full.feature_layers[cut:]), full.classifier)

        nodes.append(
            RASTNode(
                cut=cut,
                layer_name=f"feature_layer_{cut}",
                output_dim=out_dim,
                activation_bytes_per_batch=activation_bytes,
                communication_bytes_per_batch=communication_bytes,
                client_params=count_params(client_layers),
                server_params=count_params(server_layers),
                client_flops_per_sample=client_flops,
                server_flops_per_sample=server_flops,
            )
        )
    return nodes

BATCH_SIZE = 512
rast_nodes = construct_rast(input_dim, batch_size=BATCH_SIZE)
rast_df = pd.DataFrame([asdict(n) for n in rast_nodes])
print("RAST nodes:")
print(rast_df)


# %% CELL 5: Candidate Split Generator with Resource Pruning
@dataclass
class DeploymentConstraints:
    max_comm_bytes_per_batch: int = 10**9       # relaxed default
    max_client_params: int = 10**9              # relaxed default
    max_client_flops_per_sample: int = 10**9    # relaxed default
    min_cut: int = 1
    max_cut: int = 6


def generate_candidate_splits(nodes: List[RASTNode], constraints: DeploymentConstraints) -> List[RASTNode]:
    candidates = []
    for node in nodes:
        node.feasible = True
        node.reason = "OK"

        if node.cut < constraints.min_cut or node.cut > constraints.max_cut:
            node.feasible = False
            node.reason = "outside_allowed_cut_range"
        elif node.communication_bytes_per_batch > constraints.max_comm_bytes_per_batch:
            node.feasible = False
            node.reason = "communication_budget_exceeded"
        elif node.client_params > constraints.max_client_params:
            node.feasible = False
            node.reason = "client_parameter_budget_exceeded"
        elif node.client_flops_per_sample > constraints.max_client_flops_per_sample:
            node.feasible = False
            node.reason = "client_flops_budget_exceeded"

        if node.feasible:
            candidates.append(node)

    if len(candidates) == 0:
        raise ValueError("No feasible split candidates. Relax constraints.")
    return candidates

# For your current paper setting, use cuts 4,5,6 as candidate region.
# Later you can set min_cut=1,max_cut=6 or use deeper models.
constraints = DeploymentConstraints(
    max_comm_bytes_per_batch=10**9,
    max_client_params=10**9,
    max_client_flops_per_sample=10**9,
    min_cut=4,
    max_cut=6,
)

candidate_nodes = generate_candidate_splits(rast_nodes, constraints)
