# -*- coding: utf-8 -*-
"""
CA-BASL with RAST: MobileNet-style 1D Backbone
Dataset: NSL-KDD binary intrusion detection

Pipeline kept identical across all model files:
Dataset -> Backbone -> RAST Construction -> Candidate Split Nodes -> UCB Bandit -> Optimal Split -> Split Learning -> Evaluation

Run in Google Colab as a script, or paste each # %% block as a notebook cell.
"""

# %% CELL 1: Imports + Reproducibility
import time
import math
import random
from dataclasses import dataclass, asdict
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

import torch
import torch.nn as nn
from torch.utils.data import TensorDataset, DataLoader

from sklearn.preprocessing import LabelEncoder, StandardScaler
from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, roc_auc_score

SEED = 42
random.seed(SEED)
np.random.seed(SEED)
torch.manual_seed(SEED)

DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Using device:", DEVICE)


# %% CELL 2: Load + Preprocess NSL-KDD
print("Loading NSL-KDD dataset...")

train_url = "https://raw.githubusercontent.com/defcom17/NSL_KDD/master/KDDTrain+.txt"
test_url  = "https://raw.githubusercontent.com/defcom17/NSL_KDD/master/KDDTest+.txt"

columns = [
    'duration','protocol_type','service','flag','src_bytes','dst_bytes','land',
    'wrong_fragment','urgent','hot','num_failed_logins','logged_in','num_compromised',
    'root_shell','su_attempted','num_root','num_file_creations','num_shells',
    'num_access_files','num_outbound_cmds','is_host_login','is_guest_login',
    'count','srv_count','serror_rate','srv_serror_rate','rerror_rate','srv_rerror_rate',
    'same_srv_rate','diff_srv_rate','srv_diff_host_rate','dst_host_count',
    'dst_host_srv_count','dst_host_same_srv_rate','dst_host_diff_srv_rate',
    'dst_host_same_src_port_rate','dst_host_srv_diff_host_rate','dst_host_serror_rate',
    'dst_host_srv_serror_rate','dst_host_rerror_rate','dst_host_srv_rerror_rate',
    'label','difficulty'
]

train_df = pd.read_csv(train_url, header=None)
test_df = pd.read_csv(test_url, header=None)
train_df.columns = columns
test_df.columns = columns

train_df['label'] = train_df['label'].apply(lambda x: 0 if x == 'normal' else 1)
test_df['label'] = test_df['label'].apply(lambda x: 0 if x == 'normal' else 1)

categorical_cols = ['protocol_type', 'service', 'flag']
for col in categorical_cols:
    le = LabelEncoder()
    combined = pd.concat([train_df[col], test_df[col]], axis=0).astype(str)
    le.fit(combined)
    train_df[col] = le.transform(train_df[col].astype(str))
    test_df[col] = le.transform(test_df[col].astype(str))

X_train = train_df.drop(['label', 'difficulty'], axis=1).values
y_train = train_df['label'].values
X_test = test_df.drop(['label', 'difficulty'], axis=1).values
y_test = test_df['label'].values

scaler = StandardScaler()
X_train = scaler.fit_transform(X_train)
X_test = scaler.transform(X_test)

X_train_tensor = torch.tensor(X_train, dtype=torch.float32)
y_train_tensor = torch.tensor(y_train, dtype=torch.float32).view(-1, 1)
X_test_tensor = torch.tensor(X_test, dtype=torch.float32)
y_test_tensor = torch.tensor(y_test, dtype=torch.float32).view(-1, 1)

print("Train:", X_train_tensor.shape, y_train_tensor.shape)
print("Test :", X_test_tensor.shape, y_test_tensor.shape)
print("Train labels:", np.bincount(y_train))
print("Test labels :", np.bincount(y_test))


# %% CELL 3: Full Neural Network Backbone - MobileNet-style 1D
class FlatToConv1D(nn.Module):
    def forward(self, x):
        return x.unsqueeze(1)


class DepthwiseSeparableConv1D(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, stride: int = 1):
        super().__init__()
        self.net = nn.Sequential(
            nn.Conv1d(in_channels, in_channels, kernel_size=3, stride=stride, padding=1, groups=in_channels, bias=False),
            nn.BatchNorm1d(in_channels),
            nn.ReLU(),
            nn.Conv1d(in_channels, out_channels, kernel_size=1, bias=False),
            nn.BatchNorm1d(out_channels),
            nn.ReLU(),
        )
    def forward(self, x):
        return self.net(x)


class CNNClassifier(nn.Module):
    def __init__(self, in_channels: int):
        super().__init__()
        self.net = nn.Sequential(
            nn.AdaptiveAvgPool1d(1),
            nn.Flatten(),
            nn.Linear(in_channels, 64),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(64, 1),
            nn.Sigmoid(),
        )
    def forward(self, x):
        return self.net(x)


class FullIDSModel(nn.Module):
    def __init__(self, input_dim: int):
        super().__init__()
        self.input_adapter = FlatToConv1D()
        self.feature_layers = nn.ModuleList([
            nn.Sequential(nn.Conv1d(1, 16, kernel_size=3, padding=1, bias=False), nn.BatchNorm1d(16), nn.ReLU()),
            DepthwiseSeparableConv1D(16, 32, stride=1),
            DepthwiseSeparableConv1D(32, 64, stride=2),
            DepthwiseSeparableConv1D(64, 64, stride=1),
            DepthwiseSeparableConv1D(64, 128, stride=2),
            DepthwiseSeparableConv1D(128, 128, stride=1),
        ])
        self.classifier = CNNClassifier(in_channels=128)

    def forward(self, x):
        x = self.input_adapter(x)
        for block in self.feature_layers:
            x = block(x)
        return self.classifier(x)


# Instantiate backbone template
input_dim = X_train_tensor.shape[1]
full_model_template = FullIDSModel(input_dim)
print(full_model_template)
print("Number of candidate feature blocks:", len(full_model_template.feature_layers))


# %% CELL 4: RAST Node Definition + Generic Resource Profiler
@dataclass
class RASTNode:
    cut: int
    layer_name: str
    output_shape: str
    output_numel_per_sample: int
    activation_bytes_per_batch: int
    communication_bytes_per_batch: int
    client_params: int
    server_params: int
    client_param_ratio: float
    server_param_ratio: float
    feasible: bool = True
    reason: str = "OK"


def count_params(module: nn.Module) -> int:
    return sum(p.numel() for p in module.parameters() if p.requires_grad)


def module_list_params(modules: List[nn.Module]) -> int:
    return sum(count_params(m) for m in modules)


def shape_string(t: torch.Tensor) -> str:
    return "x".join(str(v) for v in list(t.shape[1:]))


def construct_rast(input_dim: int, batch_size: int = 512) -> List[RASTNode]:
    """
    Resource-Aware Split Tree (RAST).
    Each node represents a valid split immediately after one feature block.
    This profiler is architecture-agnostic: it forwards a dummy batch through the model.
    """
    full = FullIDSModel(input_dim).to(DEVICE)
    full.eval()
    dummy = torch.zeros(2, input_dim, dtype=torch.float32).to(DEVICE)

    with torch.no_grad():
        x = full.input_adapter(dummy)
        output_tensors = []
        for block in full.feature_layers:
            x = block(x)
            output_tensors.append(x.detach().cpu())

    total_params = count_params(full)
    nodes = []
    for cut, out in enumerate(output_tensors, start=1):
        out_numel = int(out[0].numel())
        activation_bytes = batch_size * out_numel * 4
        communication_bytes = 2 * activation_bytes

        client_modules = [full.input_adapter] + list(full.feature_layers[:cut])
        server_modules = list(full.feature_layers[cut:]) + [full.classifier]
        client_params = module_list_params(client_modules)
        server_params = module_list_params(server_modules)

        nodes.append(
            RASTNode(
                cut=cut,
                layer_name=f"feature_block_{cut}",
                output_shape=shape_string(out),
                output_numel_per_sample=out_numel,
                activation_bytes_per_batch=activation_bytes,
                communication_bytes_per_batch=communication_bytes,
                client_params=client_params,
                server_params=server_params,
                client_param_ratio=client_params / max(total_params, 1),
                server_param_ratio=server_params / max(total_params, 1),
            )
        )
    return nodes

BATCH_SIZE = 512
rast_nodes = construct_rast(input_dim, batch_size=BATCH_SIZE)
rast_df = pd.DataFrame([asdict(n) for n in rast_nodes])
print("RAST nodes:")
print(rast_df)


# %% CELL 5: Candidate Split Generator with Resource Pruning
@dataclass
class DeploymentConstraints:
    max_comm_bytes_per_batch: int = 10**9
    max_client_params: int = 10**9
    min_cut: int = 1
    max_cut: int = 10**9


def generate_candidate_splits(nodes: List[RASTNode], constraints: DeploymentConstraints) -> List[RASTNode]:
    candidates = []
    for node in nodes:
        node.feasible = True
        node.reason = "OK"
        if node.cut < constraints.min_cut or node.cut > constraints.max_cut:
            node.feasible = False
            node.reason = "outside_allowed_cut_range"
        elif node.communication_bytes_per_batch > constraints.max_comm_bytes_per_batch:
            node.feasible = False
            node.reason = "communication_budget_exceeded"
        elif node.client_params > constraints.max_client_params:
            node.feasible = False
            node.reason = "client_parameter_budget_exceeded"
        if node.feasible:
            candidates.append(node)
    if len(candidates) == 0:
        raise ValueError("No feasible split candidates. Relax constraints.")
    return candidates

# Default: allow all valid architecture-specific split nodes.
# You can restrict min_cut/max_cut to match a paper experiment.
constraints = DeploymentConstraints(
    max_comm_bytes_per_batch=10**9,
    max_client_params=10**9,
    min_cut=1,
    max_cut=len(rast_nodes),
)

candidate_nodes = generate_candidate_splits(rast_nodes, constraints)
candidate_df = pd.DataFrame([asdict(n) for n in candidate_nodes])
print("Candidate split nodes:")
print(candidate_df[["cut", "output_shape", "output_numel_per_sample", "communication_bytes_per_batch", "client_params", "server_params", "feasible", "reason"]])


# %% CELL 6: Deployment Utility + UCB Multi-Armed Bandit
class UCBBandit:
    def __init__(self, arms: List[int], exploration_c: float = 1.2):
        self.arms = arms
        self.c = exploration_c
        self.counts = {a: 0 for a in arms}
        self.values = {a: 0.0 for a in arms}
        self.t = 0

    def select_arm(self) -> int:
        self.t += 1
        for arm in self.arms:
            if self.counts[arm] == 0:
                return arm
        scores = {}
        for arm in self.arms:
            exploitation = self.values[arm]
            exploration = self.c * math.sqrt(math.log(self.t) / self.counts[arm])
            scores[arm] = exploitation + exploration
        return max(scores, key=scores.get)

    def update(self, arm: int, reward: float):
        self.counts[arm] += 1
        n = self.counts[arm]
        self.values[arm] += (reward - self.values[arm]) / n


def normalize(value: float, min_value: float, max_value: float) -> float:
    if max_value == min_value:
        return 0.0
    return (value - min_value) / (max_value - min_value)


def deployment_reward(
    f1: float,
    latency: float,
    comm_bytes: float,
    node: RASTNode,
    all_nodes: List[RASTNode],
    alpha: float = 1.0,
    beta: float = 0.25,
    gamma: float = 0.15,
    delta: float = 0.10,
) -> float:
    """
    Higher reward is better.
    f1 rewards detection quality.
    communication, latency, and client size are penalties.
    """
    comm_values = [n.communication_bytes_per_batch for n in all_nodes]
    param_values = [n.client_params for n in all_nodes]
    comm_norm = normalize(comm_bytes, min(comm_values), max(comm_values))
    param_norm = normalize(node.client_params, min(param_values), max(param_values))
    latency_norm = latency / max(latency, 1e-8)
    reward = alpha * f1 - beta * comm_norm - gamma * latency_norm - delta * param_norm
    return float(reward)

candidate_cuts = [n.cut for n in candidate_nodes]
bandit = UCBBandit(candidate_cuts, exploration_c=1.2)
print("Bandit arms/candidate cuts:", candidate_cuts)


# %% CELL 7: Automatic Client/Server Split Builder
class ClientSplitModel(nn.Module):
    def __init__(self, input_dim: int, cut: int):
        super().__init__()
        full = FullIDSModel(input_dim)
        self.input_adapter = full.input_adapter
        self.client = nn.Sequential(*list(full.feature_layers[:cut]))

    def forward(self, x):
        x = self.input_adapter(x)
        return self.client(x)


class ServerSplitModel(nn.Module):
    def __init__(self, input_dim: int, cut: int):
        super().__init__()
        full = FullIDSModel(input_dim)
        self.server = nn.Sequential(*list(full.feature_layers[cut:]), full.classifier)

    def forward(self, x):
        return self.server(x)


def build_split_models(input_dim: int, cut: int) -> Tuple[nn.Module, nn.Module]:
    client = ClientSplitModel(input_dim, cut).to(DEVICE)
    server = ServerSplitModel(input_dim, cut).to(DEVICE)
    return client, server


# %% CELL 8: Split Learning Train/Evaluate for One Cut
train_dataset = TensorDataset(X_train_tensor, y_train_tensor)
test_dataset = TensorDataset(X_test_tensor, y_test_tensor)
train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, shuffle=True)
test_loader = DataLoader(test_dataset, batch_size=2048, shuffle=False)


def evaluate_split(client: nn.Module, server: nn.Module) -> Dict:
    client.eval(); server.eval()
    probs_all = []
    true_all = []
    with torch.no_grad():
        for bx, by in test_loader:
            bx = bx.to(DEVICE)
            out_c = client(bx)
            probs = server(out_c).cpu().numpy()
            probs_all.append(probs)
            true_all.append(by.numpy())
    y_prob = np.vstack(probs_all)
    y_true = np.vstack(true_all)
    y_pred = (y_prob > 0.5).astype(np.float32)
    return {
        "accuracy": accuracy_score(y_true, y_pred),
        "precision": precision_score(y_true, y_pred, zero_division=0),
        "recall": recall_score(y_true, y_pred, zero_division=0),
        "f1": f1_score(y_true, y_pred, zero_division=0),
        "auc": roc_auc_score(y_true, y_prob),
    }


def train_split_once(cut: int, epochs: int = 3, lr: float = 0.001) -> Dict:
    client, server = build_split_models(input_dim, cut)
    criterion = nn.BCELoss()
    c_opt = torch.optim.Adam(client.parameters(), lr=lr)
    s_opt = torch.optim.Adam(server.parameters(), lr=lr)

    start = time.time()
    client.train(); server.train()
    total_comm_bytes = 0

    for epoch in range(epochs):
        total_loss = 0.0
        for bx, by in train_loader:
            bx = bx.to(DEVICE)
            by = by.to(DEVICE)
            c_opt.zero_grad()
            s_opt.zero_grad()

            client_out = client(bx)
            server_in = client_out.detach().requires_grad_()
            preds = server(server_in)
            loss = criterion(preds, by)
            loss.backward()
            client_out.backward(server_in.grad)
            c_opt.step()
            s_opt.step()

            total_comm_bytes += 2 * client_out.numel() * 4
            total_loss += loss.item()

    latency = time.time() - start
    metrics = evaluate_split(client, server)
    metrics.update({"cut": cut, "latency": latency, "comm_bytes": total_comm_bytes, "epochs": epochs})
    return metrics


# %% CELL 9: CA-BASL Adaptive Bandit Loop
ROUNDS = 8
EPOCHS_PER_ROUND = 2
LR = 0.001

history = []
print("Starting CA-BASL adaptive loop...")

for r in range(1, ROUNDS + 1):
    selected_cut = bandit.select_arm()
    selected_node = next(n for n in rast_nodes if n.cut == selected_cut)
    print(f"\nRound {r}/{ROUNDS}: Bandit selected Cut {selected_cut}")

    result = train_split_once(selected_cut, epochs=EPOCHS_PER_ROUND, lr=LR)
    reward = deployment_reward(
        f1=result["f1"],
        latency=result["latency"],
        comm_bytes=selected_node.communication_bytes_per_batch,
        node=selected_node,
        all_nodes=candidate_nodes,
        alpha=1.0,
        beta=0.25,
        gamma=0.15,
        delta=0.10,
    )
    bandit.update(selected_cut, reward)

    row = {
        "round": r,
        "selected_cut": selected_cut,
        "reward": reward,
        **result,
        "rast_comm_bytes_per_batch": selected_node.communication_bytes_per_batch,
        "client_params": selected_node.client_params,
        "server_params": selected_node.server_params,
    }
    history.append(row)
    print(
        f"Cut {selected_cut} | Acc={result['accuracy']:.4f} | F1={result['f1']:.4f} | "
        f"AUC={result['auc']:.4f} | Latency={result['latency']:.2f}s | Reward={reward:.4f}"
    )

history_df = pd.DataFrame(history)
print("\nCA-BASL history:")
print(history_df)
print("\nBandit values:", bandit.values)
print("Bandit counts:", bandit.counts)

best_round = history_df.loc[history_df["reward"].idxmax()]
best_cut = int(best_round["selected_cut"])
print("\nBest cut found by CA-BASL:", best_cut)


# %% CELL 10: Fixed-Cut Baseline Comparison
print("\nRunning fixed-cut baselines for comparison...")
fixed_results = []
for cut in candidate_cuts:
    res = train_split_once(cut, epochs=EPOCHS_PER_ROUND, lr=LR)
    node = next(n for n in rast_nodes if n.cut == cut)
    res["rast_comm_bytes_per_batch"] = node.communication_bytes_per_batch
    res["client_params"] = node.client_params
    res["server_params"] = node.server_params
    fixed_results.append(res)
    print(f"Fixed Cut {cut}: Acc={res['accuracy']:.4f}, F1={res['f1']:.4f}, AUC={res['auc']:.4f}, Latency={res['latency']:.2f}s")

fixed_df = pd.DataFrame(fixed_results)
print("\nFixed baseline results:")
print(fixed_df)


# %% CELL 11: Visualizations
plt.figure(figsize=(7, 4))
