N_ROUNDS = 8
UCB_C = 1.2
SEED = 42


# ============================================================
# 2. GENERIC UCB SEARCH
# ============================================================

def run_ucb(candidate_cuts, n_rounds=8, c=1.2):
    """
    Run UCB over already-computed split rewards.

    No neural-network retraining is performed.
    """

    counts = {cut: 0 for cut in candidate_cuts}
    means = {cut: 0.0 for cut in candidate_cuts}

    history = []

    for t in range(1, n_rounds + 1):

        # ----------------------------------------------------
        # Initial exploration:
        # evaluate every candidate once
        # ----------------------------------------------------
        unvisited = [
            cut for cut in candidate_cuts
            if counts[cut] == 0
        ]

        if unvisited:
            selected_cut = unvisited[0]

        else:

            ucb_scores = {}

            for cut in candidate_cuts:

                exploitation = means[cut]

                exploration = c * np.sqrt(
                    np.log(t) / counts[cut]
                )

                ucb_scores[cut] = (
                    exploitation + exploration
                )

            selected_cut = max(
                ucb_scores,
                key=ucb_scores.get
            )

        # ----------------------------------------------------
        # Observe existing experimental reward
        # ----------------------------------------------------
        reward = CUT_RESULTS[selected_cut]["reward"]

        # ----------------------------------------------------
        # Update UCB statistics
        # ----------------------------------------------------
        counts[selected_cut] += 1

        n = counts[selected_cut]

        means[selected_cut] += (
            reward - means[selected_cut]
        ) / n

        history.append({
            "round": t,
            "cut": selected_cut,
            "reward": reward
        })

    df = pd.DataFrame(history)

    df["best_reward"] = df["reward"].cummax()

    return df


# ============================================================
# 3. DA-UCB WITHOUT RAST
# ============================================================

no_rast_history = run_ucb(
    candidate_cuts=ALL_CUTS,
    n_rounds=N_ROUNDS,
    c=UCB_C
)


# ============================================================
# 4. CA-BASL = RAST + DA-UCB
# ============================================================

cabasl_history = run_ucb(
    candidate_cuts=RAST_CUTS,
    n_rounds=N_ROUNDS,
    c=UCB_C
)


# ============================================================
# 5. RANDOM SEARCH OVER ALL SPLITS
# ============================================================

rng = np.random.default_rng(SEED)

