def first_optimal_round(df, optimum):

    matches = df[
        np.isclose(
            df["best_reward"],
            optimum,
            atol=1e-8
        )
    ]

    if len(matches) == 0:
        return "Not reached"

    return int(matches.iloc[0]["round"])


