# ================================================================
# 3. NORMALIZATION
# ================================================================

def minmax(values):

    values = np.asarray(values, dtype=float)

    vmin = values.min()
    vmax = values.max()

    if np.isclose(vmax, vmin):
        return np.zeros_like(values)

    return (values - vmin) / (vmax - vmin)


# ================================================================
# 4. COMPUTE DEPLOYMENT REWARDS
# ================================================================

def calculate_rewards(results, candidate_cuts, beta):

    """
    Reward:

        R = alpha * F1
            - beta  * normalized communication
            - gamma * normalized latency
            - delta * normalized client FLOPs

    Normalization is performed across the candidate configurations
    supplied to the optimizer.
    """

    f1 = np.array([
        results[c]["f1"]
        for c in candidate_cuts
    ])

    comm = np.array([
        results[c]["comm"]
        for c in candidate_cuts
    ])

    latency = np.array([
        results[c]["latency"]
        for c in candidate_cuts
    ])

    flops = np.array([
        results[c]["client_flops"]
        for c in candidate_cuts
    ])

    comm_norm = minmax(comm)
    latency_norm = minmax(latency)
    flops_norm = minmax(flops)

    rewards = {}

    for i, cut in enumerate(candidate_cuts):

        reward = (
            ALPHA * f1[i]
            - beta * comm_norm[i]
            - GAMMA * latency_norm[i]
            - DELTA * flops_norm[i]
        )

        rewards[cut] = float(reward)

    return rewards


# ================================================================
# 5. DA-UCB
# ================================================================

def run_ucb(candidate_cuts, rewards, n_rounds=8, c=1.2):

    counts = {
        cut: 0
        for cut in candidate_cuts
    }

    means = {
        cut: 0.0
        for cut in candidate_cuts
    }

    history = []

    for t in range(1, n_rounds + 1):

        # Initial exploration:
        # every feasible candidate is evaluated once.

        unvisited = [
            cut
            for cut in candidate_cuts
            if counts[cut] == 0
        ]

        if unvisited:

            selected_cut = unvisited[0]

        else:

            scores = {}

            for cut in candidate_cuts:

                exploitation = means[cut]

                exploration = (
                    c
                    * np.sqrt(
                        np.log(t)
                        / counts[cut]
                    )
                )

                scores[cut] = (
                    exploitation
                    + exploration
                )

            selected_cut = max(
                scores,
                key=scores.get
            )

        reward = rewards[selected_cut]

        counts[selected_cut] += 1

        n = counts[selected_cut]

        means[selected_cut] += (
            reward - means[selected_cut]
        ) / n

        history.append({

            "round": t,
            "cut": selected_cut,
            "reward": reward,

            "best_reward":
                max(
                    [x["reward"] for x in history]
                    + [reward]
                )
        })

    return pd.DataFrame(history)


# ================================================================
# 6. EXPLORATION-COEFFICIENT ABLATION
# ================================================================

def run_c_ablation(
    backbone,
    results,
    rast_cuts
):

    # beta remains at default value
    rewards = calculate_rewards(
        results,
        rast_cuts,
        DEFAULT_BETA
    )

    rows = []
    histories = {}

    for c_value in C_VALUES:

        history = run_ucb(
            rast_cuts,
            rewards,
            N_ROUNDS,
            c_value
        )

        histories[c_value] = history

        # Best configuration actually encountered
        best_idx = history["reward"].idxmax()

        best_cut = int(
            history.loc[best_idx, "cut"]
        )

        best_reward = float(
            history.loc[best_idx, "reward"]
        )

        unique_splits = int(
            history["cut"].nunique()
        )

        final_selected = int(
            history.iloc[-1]["cut"]
        )

        rows.append({

            "Backbone": backbone,
            "c": c_value,
            "Best Split": f"S{best_cut}",
            "Final Selected Split":
                f"S{final_selected}",
            "F1":
                results[best_cut]["f1"],
            "Communication (MB)":
                results[best_cut]["comm"] / 1e6,
            "Client FLOPs":
                results[best_cut]["client_flops"],
            "Latency (s)":
                results[best_cut]["latency"],
            "Best Reward":
                best_reward,
            "Unique Splits":
                unique_splits
        })

    return pd.DataFrame(rows), histories


# ================================================================
# 7. COMMUNICATION-WEIGHT BETA ABLATION
# ================================================================

def run_beta_ablation(
    backbone,
    results,
    rast_cuts
):

    rows = []
    histories = {}

    for beta in BETA_VALUES:

        # IMPORTANT:
        # reward must be recomputed for every beta.

        rewards = calculate_rewards(
            results,
            rast_cuts,
            beta
        )

        history = run_ucb(
            rast_cuts,
            rewards,
            N_ROUNDS,
            DEFAULT_C
        )

        histories[beta] = history

        best_idx = history["reward"].idxmax()

        best_cut = int(
            history.loc[best_idx, "cut"]
        )

        best_reward = float(
            history.loc[best_idx, "reward"]
        )

        rows.append({

            "Backbone": backbone,
            "beta": beta,
            "Selected Split":
                f"S{best_cut}",
            "F1":
                results[best_cut]["f1"],
            "Communication (MB)":
                results[best_cut]["comm"] / 1e6,
            "Client FLOPs":
                results[best_cut]["client_flops"],
            "Latency (s)":
                results[best_cut]["latency"],
            "Reward":
                best_reward
        })

    return pd.DataFrame(rows), histories


