# =============================================================================
# 6. BASIC BUILDING BLOCKS
# =============================================================================

class ResidualMLPBlock(nn.Module):

    def __init__(self, dim):
        super().__init__()

        self.block = nn.Sequential(
            nn.Linear(dim, dim),
            nn.ReLU(),
            nn.Linear(dim, dim)
        )

        self.relu = nn.ReLU()

    def forward(self, x):
        return self.relu(
            x + self.block(x)
        )


class DepthwiseSeparableBlock(nn.Module):
    """
    Lightweight MobileNet-style block for tabular 1D feature representations.

    The depthwise operation is implemented through grouped Conv1d.
    """

    def __init__(self, in_channels, out_channels):
        super().__init__()

        self.depthwise = nn.Conv1d(
            in_channels,
            in_channels,
            kernel_size=1,
            groups=in_channels,
            bias=True
        )

        self.pointwise = nn.Conv1d(
            in_channels,
            out_channels,
            kernel_size=1,
            bias=True
        )

        self.activation = nn.ReLU()

    def forward(self, x):

        # [B,D] -> [B,D,1]
        x = x.unsqueeze(-1)

        x = self.depthwise(x)
        x = self.pointwise(x)
        x = self.activation(x)

        # [B,D,1] -> [B,D]
        return x.squeeze(-1)


class MBConvTabular(nn.Module):
    """
    Simplified EfficientNet-style inverted bottleneck block.
    """

    def __init__(
        self,
        in_dim,
        out_dim,
        expansion=2
    ):
        super().__init__()

        hidden = in_dim * expansion

        self.expand = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.SiLU()
        )

        self.project = nn.Sequential(
            nn.Linear(hidden, out_dim),
            nn.SiLU()
        )

        self.use_residual = (
            in_dim == out_dim
        )

    def forward(self, x):

        out = self.expand(x)
        out = self.project(out)

        if self.use_residual:
            out = out + x

        return out


class TransformerFeatureBlock(nn.Module):

    def __init__(
        self,
        dim,
        nhead=4,
        ff_mult=2
    ):
        super().__init__()

        layer = nn.TransformerEncoderLayer(
            d_model=dim,
            nhead=nhead,
            dim_feedforward=dim * ff_mult,
            dropout=0.0,
            batch_first=True,
            activation="gelu"
        )

        self.encoder = nn.TransformerEncoder(
            layer,
            num_layers=1
        )

    def forward(self, x):

        # Treat representation as a single token.
        x = x.unsqueeze(1)

        x = self.encoder(x)

        return x.squeeze(1)


# =============================================================================
# 7. ARCHITECTURE DEFINITIONS
# =============================================================================
#
# Each backbone is represented as:
#
#     feature blocks -> binary classifier
#
# Candidate split Si means:
#
#     client = blocks [0:i]
#     server = blocks [i:]
#
# =============================================================================


def build_cnn():

    dims = [
        INPUT_DIM,
        128,
        96,
        64,
        48,
        32,
        16
    ]

    blocks = []

    for i in range(len(dims) - 1):

        blocks.append(
            nn.Sequential(
                nn.Linear(
                    dims[i],
                    dims[i + 1]
                ),
                nn.ReLU()
            )
        )

    classifier = nn.Linear(
        dims[-1],
        1
    )

    return blocks, classifier, dims[1:]


def build_mobilenet():

    dims = [
        INPUT_DIM,
        128,
        96,
        64,
        48,
        32,
        16
    ]

    blocks = []

    # Initial projection
    blocks.append(
        nn.Sequential(
            nn.Linear(INPUT_DIM, 128),
            nn.ReLU()
        )
    )

    # MobileNet-style depthwise separable stages
    for in_d, out_d in zip(
        dims[1:-1],
        dims[2:]
    ):
        blocks.append(
            DepthwiseSeparableBlock(
                in_d,
                out_d
            )
        )

    classifier = nn.Linear(
        dims[-1],
        1
    )

    return blocks, classifier, dims[1:]


def build_efficientnet():

    dims = [
        INPUT_DIM,
        128,
        96,
        64,
        48,
        32,
        16
    ]

    blocks = []

    blocks.append(
        nn.Sequential(
            nn.Linear(INPUT_DIM, 128),
            nn.SiLU()
        )
    )

    for in_d, out_d in zip(
        dims[1:-1],
        dims[2:]
    ):
        blocks.append(
            MBConvTabular(
                in_d,
                out_d,
                expansion=2
            )
        )

    classifier = nn.Linear(
        dims[-1],
        1
    )

    return blocks, classifier, dims[1:]


def build_transformer():

    dims = [
        INPUT_DIM,
        128,
        96,
        64,
        48,
        32,
        16
    ]

    blocks = []

    # Input embedding
    blocks.append(
        nn.Sequential(
            nn.Linear(INPUT_DIM, 128),
            nn.GELU()
        )
    )

    # Transformer + dimensional reduction stages
    transition_dims = [
        (128, 96),
        (96, 64),
        (64, 48),
        (48, 32),
        (32, 16)
    ]

    for in_d, out_d in transition_dims:

        # choose valid head count
        if in_d % 8 == 0:
            nhead = 8
        elif in_d % 4 == 0:
            nhead = 4
        elif in_d % 2 == 0:
            nhead = 2
        else:
            nhead = 1

        blocks.append(
            nn.Sequential(
                TransformerFeatureBlock(
                    in_d,
                    nhead=nhead
                ),
                nn.Linear(
                    in_d,
                    out_d
                ),
                nn.GELU()
            )
        )

    classifier = nn.Linear(
        dims[-1],
        1
    )

    return blocks, classifier, dims[1:]


ARCHITECTURES = {
    "CNN": build_cnn,
    "MobileNet": build_mobilenet,
    "EfficientNet": build_efficientnet,
    "Transformer": build_transformer
}


# =============================================================================
# 8. SPLIT MODEL
# =============================================================================

class SplitNetwork(nn.Module):

    def __init__(
        self,
        blocks,
        classifier,
        cut
    ):
        super().__init__()

        self.client = nn.Sequential(
            *blocks[:cut]
        )

        self.server = nn.Sequential(
            *blocks[cut:]
        )

        self.classifier = classifier

    def forward(self, x):

        smashed = self.client(x)

        server_output = self.server(smashed)

        logits = self.classifier(
            server_output
        )

        return logits.squeeze(-1)


# =============================================================================
# 9. PARAMETER COUNT
# =============================================================================

def parameter_count(module):

    return sum(
        p.numel()
        for p in module.parameters()
    )


# =============================================================================
# 10. APPROXIMATE FLOP COUNT
# =============================================================================
#
# Linear:
#     approximately 2 * in_features * out_features
#
# Conv1d:
#     approximately
#     2 * output_channels * (input_channels/groups) * kernel_size
#
# Transformer:
#     approximate projection + feedforward operations.
#
# This is used consistently across all newly evaluated architectures.
# =============================================================================

def module_flops(module):

    total = 0

    for m in module.modules():

        if isinstance(m, nn.Linear):

            total += (
                2
                * m.in_features
                * m.out_features
            )

        elif isinstance(m, nn.Conv1d):

            total += (
                2
                * m.out_channels
                * (m.in_channels / m.groups)
                * m.kernel_size[0]
            )

        elif isinstance(
            m,
            nn.MultiheadAttention
        ):

            d = m.embed_dim

            # Q,K,V + output projection
            total += 8 * d * d

    return float(total)


# =============================================================================
# 11. BUILD A FRESH MODEL FOR EACH SPLIT
# =============================================================================

def build_split_model(
    builder,
    cut
):

    blocks, classifier, dims = builder()

    model = SplitNetwork(
        blocks,
        classifier,
        cut
    )

    return model, dims


# =============================================================================
# 12. RESOURCE PROFILE
# =============================================================================

def profile_architecture(
    architecture_name,
    builder
):

    blocks, classifier, dims = builder()

    n_cuts = len(blocks)

    profiles = []

    for cut in range(
        1,
        n_cuts + 1
    ):

        model, _ = build_split_model(
            builder,
            cut
        )

        activation_dim = dims[
            cut - 1
        ]

        communication_bytes = (
            2
            * TRAIN_BATCH_SIZE
            * activation_dim
            * 4
        )

        client_flops = module_flops(
            model.client
        )

        server_flops = (
            module_flops(model.server)
            + module_flops(
                model.classifier
            )
        )

        client_params = parameter_count(
            model.client
        )

        server_params = (
            parameter_count(model.server)
            + parameter_count(
                model.classifier
            )
        )

        profiles.append({
            "architecture":
                architecture_name,

            "cut":
                cut,

            "activation_dim":
                activation_dim,

            "communication_bytes":
                float(
                    communication_bytes
                ),

            "client_flops":
                float(client_flops),

            "server_flops":
                float(server_flops),

            "client_params":
                float(client_params),

            "server_params":
                float(server_params)
        })

    return profiles


# =============================================================================
# 13. TRAIN/EVALUATE ONE SPLIT
# =============================================================================

def evaluate_split(
    architecture_name,
    builder,
    cut
):

    # ---------------------------------------------------------------------
    # Reset seed before every split
    # ---------------------------------------------------------------------

    random.seed(SEED)
    np.random.seed(SEED)
    torch.manual_seed(SEED)

    model, dims = build_split_model(
        builder,
        cut
    )

    model = model.to(DEVICE)

    train_generator = torch.Generator()
    train_generator.manual_seed(SEED)

    train_loader = DataLoader(
        train_dataset,
        batch_size=TRAIN_BATCH_SIZE,
        shuffle=True,
        generator=train_generator
    )

    test_loader = DataLoader(
        test_dataset,
        batch_size=TEST_BATCH_SIZE,
        shuffle=False
    )

    criterion = nn.BCEWithLogitsLoss()

    optimizer = torch.optim.Adam(
        model.parameters(),
        lr=LEARNING_RATE
    )

    # ---------------------------------------------------------------------
    # Training
    # ---------------------------------------------------------------------

    model.train()

    start_time = time.perf_counter()

    for epoch in range(
        EPOCHS_PER_SPLIT
    ):

        for xb, yb in train_loader:

            xb = xb.to(DEVICE)
            yb = yb.to(DEVICE)

            optimizer.zero_grad()

            logits = model(xb)

            loss = criterion(
                logits,
                yb
            )

            loss.backward()

            optimizer.step()

    elapsed = (
        time.perf_counter()
        - start_time
    )

    # ---------------------------------------------------------------------
    # Evaluation
    # ---------------------------------------------------------------------

    model.eval()

    probs = []
    labels = []

    with torch.no_grad():

        for xb, yb in test_loader:

            xb = xb.to(DEVICE)

            logits = model(xb)

            p = torch.sigmoid(
                logits
            )

            probs.extend(
                p.cpu()
                .numpy()
                .tolist()
            )

            labels.extend(
                yb.numpy()
                .tolist()
            )

    probs = np.asarray(probs)

    labels = np.asarray(
        labels,
        dtype=int
    )

    preds = (
        probs >= 0.5
    ).astype(int)

    accuracy = accuracy_score(
        labels,
        preds
    )

    precision = precision_score(
        labels,
        preds,
        zero_division=0
    )

    recall = recall_score(
        labels,
        preds,
        zero_division=0
    )

    f1 = f1_score(
        labels,
        preds,
        zero_division=0
    )

    try:

        auc = roc_auc_score(
            labels,
            probs
        )

    except Exception:

        auc = np.nan

    # ---------------------------------------------------------------------
    # Resource profile
    # ---------------------------------------------------------------------

    activation_dim = dims[
        cut - 1
    ]

    communication_bytes = (
        2
        * TRAIN_BATCH_SIZE
        * activation_dim
        * 4
    )

    client_flops = module_flops(
        model.client
    )

    server_flops = (
        module_flops(model.server)
        + module_flops(
            model.classifier
        )
    )

    client_params = parameter_count(
        model.client
    )

    server_params = (
        parameter_count(model.server)
        + parameter_count(
            model.classifier
        )
    )

    return {

        "architecture":
            architecture_name,

        "cut":
            cut,

        "accuracy":
            float(accuracy),

        "precision":
            float(precision),

        "recall":
            float(recall),

        "f1":
            float(f1),

        "auc":
            float(auc),

        "communication_bytes":
            float(
                communication_bytes
            ),

        "client_flops":
            float(client_flops),

        "server_flops":
            float(server_flops),

        "client_params":
            float(client_params),

        "server_params":
            float(server_params),

        "latency":
            float(elapsed)
    }


# =============================================================================
# 14. REWARD CALCULATION
# =============================================================================
#
# Normalize deployment costs independently within each architecture.
#
# Higher reward = better.
#
# R = alpha * F1
#     - beta  * normalized communication
#     - gamma * normalized latency
#     - delta * normalized client computation
#
# =============================================================================

def minmax(values):

    values = np.asarray(
        values,
        dtype=float
    )

    lo = values.min()
    hi = values.max()

    if np.isclose(
        hi,
        lo
    ):
        return np.zeros_like(values)

    return (
        values - lo
    ) / (
        hi - lo
    )


def calculate_rewards(df):

    df = df.copy()

    comm_norm = minmax(
        df["communication_bytes"]
    )

    latency_norm = minmax(
        df["latency"]
    )

    client_flops_norm = minmax(
        df["client_flops"]
    )

    df["reward"] = (
        ALPHA * df["f1"].values
        - BETA * comm_norm
        - GAMMA * latency_norm
        - DELTA * client_flops_norm
    )

    return df


# =============================================================================
# 15. RAST FEASIBILITY
# =============================================================================
#
# To preserve the same practical filtering behaviour used in the previous
# experiments, retain the three deepest / lowest-communication candidate
# partitions.
#
# =============================================================================

def get_rast_cuts(df):

    ranked = (
        df.sort_values(
            "communication_bytes",
            ascending=True
        )
        .head(3)
    )

    return sorted(
        ranked["cut"]
        .astype(int)
        .tolist()
    )


# =============================================================================
# 16. DA-UCB
# =============================================================================

def run_ucb(
    candidate_cuts,
    cut_results,
    n_rounds=N_ROUNDS,
    c=UCB_C
):

    counts = {
        cut: 0
        for cut in candidate_cuts
    }

    means = {
        cut: 0.0
        for cut in candidate_cuts
    }

    history = []

    for t in range(
        1,
        n_rounds + 1
    ):

        unvisited = [
            cut
            for cut in candidate_cuts
            if counts[cut] == 0
        ]

        if unvisited:

            selected_cut = (
                unvisited[0]
            )

        else:

            scores = {}

            for cut in candidate_cuts:

                exploitation = (
                    means[cut]
                )

                exploration = (
                    c
                    * np.sqrt(
                        np.log(t)
                        / counts[cut]
                    )
                )

                scores[cut] = (
                    exploitation
                    + exploration
                )

            selected_cut = max(
                scores,
                key=scores.get
            )

        reward = (
            cut_results[
                selected_cut
            ]["reward"]
        )

        counts[
            selected_cut
        ] += 1

        n = counts[
            selected_cut
        ]

        means[
            selected_cut
        ] += (
            reward
            - means[
                selected_cut
            ]
        ) / n

        history.append({

            "round":
                t,

            "cut":
                selected_cut,

            "reward":
                reward
        })

    history = pd.DataFrame(
        history
    )

    history[
        "best_reward"
    ] = (
        history["reward"]
        .cummax()
    )

    return history


# =============================================================================
# 17. RANDOM SEARCH
# =============================================================================

def run_random_search(
    candidate_cuts,
    cut_results,
    n_rounds=N_ROUNDS,
    seed=SEED
):

    rng = np.random.default_rng(
        seed
    )

    history = []

    best = -np.inf

    for t in range(
        1,
        n_rounds + 1
    ):

        cut = int(
            rng.choice(
                candidate_cuts
            )
        )

        reward = (
            cut_results[
                cut
            ]["reward"]
        )

        best = max(
            best,
            reward
        )

        history.append({

            "round":
                t,

            "cut":
                cut,

            "reward":
                reward,

            "best_reward":
                best
        })

    return pd.DataFrame(
        history
    )


# =============================================================================
# 18. EXHAUSTIVE SEARCH
# =============================================================================

def run_exhaustive(
    candidate_cuts,
    cut_results
):

    history = []

    best = -np.inf

    for t, cut in enumerate(
        candidate_cuts,
        start=1
    ):

        reward = (
            cut_results[
                cut
            ]["reward"]
        )

        best = max(
            best,
            reward
        )

        history.append({

            "round":
                t,

            "cut":
                cut,

            "reward":
                reward,

            "best_reward":
                best
        })

    return pd.DataFrame(
        history
    )


# =============================================================================
# 19. FIRST ROUND REACHING OPTIMUM
# =============================================================================

def first_optimal_round(
    df,
    optimum
):

    matches = df[
        np.isclose(
            df["best_reward"],
            optimum,
            atol=1e-8
        )
    ]

    if len(matches) == 0:
        return np.nan

    return int(
        matches.iloc[0][
            "round"
        ]
    )


# =============================================================================
# 20. RUN ONE ARCHITECTURE
# =============================================================================

def run_architecture(
    architecture_name,
    builder
):

    print(
        "\n\n"
        + "#" * 90
    )

    print(
        architecture_name.upper()
    )

    print(
        "#" * 90
    )

    # ---------------------------------------------------------------------
    # Resource profiles
    # ---------------------------------------------------------------------

    profiles = profile_architecture(
        architecture_name,
        builder
    )

    print(
        "\nRESOURCE PROFILES"
    )

    for p in profiles:
        print(
            "S" + str(p["cut"]),
            p
        )

    # ---------------------------------------------------------------------
    # Evaluate every split
    # ---------------------------------------------------------------------

    results = []

    for profile in profiles:

        cut = profile["cut"]

        print(
            f"\nEvaluating "
            f"{architecture_name} "
            f"split S{cut} ..."
        )

        result = evaluate_split(
            architecture_name,
            builder,
            cut
        )

        print(result)

        results.append(
            result
        )

    results_df = pd.DataFrame(
        results
    )

    # ---------------------------------------------------------------------
    # Reward
    # ---------------------------------------------------------------------

    results_df = calculate_rewards(
        results_df
    )

    print(
        "\nFINAL CUT RESULTS"
    )

    print(
        results_df.to_string(
            index=False
        )
    )

    # ---------------------------------------------------------------------
    # RAST
    # ---------------------------------------------------------------------

    ALL_CUTS = (
        results_df["cut"]
        .astype(int)
        .tolist()
    )

    RAST_CUTS = get_rast_cuts(
        results_df
    )

    print(
        "\nALL CUTS:",
        ALL_CUTS
    )

    print(
        "RAST FEASIBLE CUTS:",
        RAST_CUTS
    )

    # ---------------------------------------------------------------------
    # Dictionary used by searches
    # ---------------------------------------------------------------------

    cut_results = {}

    for _, row in (
        results_df.iterrows()
    ):

        cut_results[
            int(row["cut"])
        ] = row.to_dict()

    # ---------------------------------------------------------------------
    # CA-BASL
    # ---------------------------------------------------------------------

    cabasl = run_ucb(
        RAST_CUTS,
        cut_results
    )

    # ---------------------------------------------------------------------
    # DA-UCB without RAST
    # ---------------------------------------------------------------------

    no_rast = run_ucb(
        ALL_CUTS,
        cut_results
    )

    # ---------------------------------------------------------------------
    # RAST + Random
    # ---------------------------------------------------------------------

    rast_random = (
        run_random_search(
            RAST_CUTS,
            cut_results
        )
    )

    # ---------------------------------------------------------------------
    # Random Search
    # ---------------------------------------------------------------------

    random_search = (
        run_random_search(
            ALL_CUTS,
            cut_results
        )
    )

    # ---------------------------------------------------------------------
    # Exhaustive
    # ---------------------------------------------------------------------

    exhaustive = run_exhaustive(
        ALL_CUTS,
        cut_results
    )

    # ---------------------------------------------------------------------
    # Global optimum
    # ---------------------------------------------------------------------

    optimum_idx = (
        results_df["reward"]
        .idxmax()
    )

    optimum_row = (
        results_df.loc[
            optimum_idx
        ]
    )

    optimal_cut = int(
        optimum_row["cut"]
    )

    optimal_reward = float(
        optimum_row["reward"]
    )

    # ---------------------------------------------------------------------
    # Print histories
    # ---------------------------------------------------------------------

    histories = {

        "CA-BASL":
            cabasl,

        "DA-UCB without RAST":
            no_rast,

        "RAST + Random":
            rast_random,

        "Random Search":
            random_search,

        "Exhaustive Search":
            exhaustive
    }

    for method, history in (
        histories.items()
    ):

        print(
            "\n"
            + "=" * 75
        )

        print(
            architecture_name,
            "--",
            method
        )

        print(
            "=" * 75
        )

        print(
            history.to_string(
                index=False
            )
        )

    print(
        "\nGLOBAL OPTIMUM"
    )

    print(
        "Optimal cut    : S"
        + str(optimal_cut)
    )

    print(
        "Optimal reward :",
        optimal_reward
    )

    print(
        "\nFIRST ROUND REACHING "
        "GLOBAL OPTIMUM"
    )

    for method, history in (
        histories.items()
    ):

        print(
            f"{method:25s}:",
            first_optimal_round(
                history,
                optimal_reward
            )
        )

    # ---------------------------------------------------------------------
    # Summary row for architecture comparison
    # ---------------------------------------------------------------------

    best = optimum_row

    summary = {

        "Backbone":
            architecture_name,

        "Selected Split":
            "S" + str(
                optimal_cut
            ),

        "Accuracy":
            best["accuracy"],

        "Precision":
            best["precision"],

        "Recall":
            best["recall"],

        "F1":
            best["f1"],

        "ROC-AUC":
            best["auc"],

        "Communication (MB)":
            best[
                "communication_bytes"
            ] / 1e6,

        "Client FLOPs":
            best[
                "client_flops"
            ],

        "Server FLOPs":
            best[
                "server_flops"
            ],

        "Client Params":
            best[
                "client_params"
            ],

        "Latency (s)":
            best["latency"],

        "Reward":
            best["reward"],

        "Total Candidate Splits":
            len(ALL_CUTS),

        "RAST Candidate Splits":
            len(RAST_CUTS),

        "Search Reduction (%)":
            (
                1
                - len(RAST_CUTS)
                / len(ALL_CUTS)
            ) * 100,

        "First Optimal Round":
            first_optimal_round(
                cabasl,
                optimal_reward
            )
    }

    # ---------------------------------------------------------------------
    # Save architecture-specific files
    # ---------------------------------------------------------------------

    safe_name = (
        architecture_name
        .replace(" ", "_")
    )

    results_df.to_csv(
        f"NSLKDD_{safe_name}_split_results.csv",
        index=False
    )

    for method, history in (
        histories.items()
    ):

        method_name = (
            method
            .replace(" ", "_")
            .replace("+", "plus")
        )

        history.to_csv(
            f"NSLKDD_{safe_name}_{method_name}.csv",
            index=False
        )

    return (
        results_df,
        histories,
        summary
    )


