# =============================================================================
# 16. MODEL BLOCKS
# =============================================================================

class ResidualBlock(nn.Module):

    def __init__(
        self,
        in_dim,
        out_dim
    ):

        super().__init__()

        self.fc1 = nn.Linear(
            in_dim,
            out_dim
        )

        self.fc2 = nn.Linear(
            out_dim,
            out_dim
        )

        self.relu = nn.ReLU()

        if in_dim != out_dim:

            self.shortcut = nn.Linear(
                in_dim,
                out_dim
            )

        else:

            self.shortcut = nn.Identity()


    def forward(
        self,
        x
    ):

        identity = self.shortcut(
            x
        )

        out = self.relu(
            self.fc1(x)
        )

        out = self.fc2(
            out
        )

        out = (
            out
            +
            identity
        )

        return self.relu(
            out
        )


class DepthwiseSeparableBlock(nn.Module):

    def __init__(
        self,
        in_channels,
        out_channels
    ):

        super().__init__()

        self.depthwise = nn.Conv1d(

            in_channels,
            in_channels,

            kernel_size=1,

            groups=in_channels
        )

        self.pointwise = nn.Conv1d(

            in_channels,
            out_channels,

            kernel_size=1
        )

        self.relu = nn.ReLU()


    def forward(
        self,
        x
    ):

        x = x.unsqueeze(
            -1
        )

        x = self.depthwise(
            x
        )

        x = self.pointwise(
            x
        )

        x = self.relu(
            x
        )

        return x.squeeze(
            -1
        )


class MBConvTabular(nn.Module):

    def __init__(
        self,
        in_dim,
        out_dim,
        expansion=2
    ):

        super().__init__()

        hidden_dim = (
            in_dim
            *
            expansion
        )

        self.expand = nn.Sequential(

            nn.Linear(
                in_dim,
                hidden_dim
            ),

            nn.SiLU()
        )

        self.project = nn.Sequential(

            nn.Linear(
                hidden_dim,
                out_dim
            ),

            nn.SiLU()
        )

        self.use_skip = (
            in_dim
            ==
            out_dim
        )


    def forward(
        self,
        x
    ):

        out = self.expand(
            x
        )

        out = self.project(
            out
        )

        if self.use_skip:

            out = (
                out
                +
                x
            )

        return out


class TransformerFeatureBlock(nn.Module):

    def __init__(
        self,
        dim,
        nhead
    ):

        super().__init__()

        layer = nn.TransformerEncoderLayer(

            d_model=dim,

            nhead=nhead,

            dim_feedforward=(
                dim * 2
            ),

            dropout=0.0,

            batch_first=True,

            activation="gelu"
        )

        self.encoder = nn.TransformerEncoder(

            layer,

            num_layers=1
        )


    def forward(
        self,
        x
    ):

        x = x.unsqueeze(
            1
        )

        x = self.encoder(
            x
        )

        return x.squeeze(
            1
        )


# =============================================================================
# 17. BACKBONE BUILDERS
# =============================================================================

def build_mlp():

    dims = [
        INPUT_DIM,
        128,
        96,
        64,
        48,
        32,
        16
    ]

    blocks = []

    for i in range(
        len(dims) - 1
    ):

        blocks.append(

            nn.Sequential(

                nn.Linear(
                    dims[i],
                    dims[i + 1]
                ),

                nn.ReLU()
            )
        )

    classifier = nn.Linear(
        16,
        1
    )

    return (
        blocks,
        classifier,
        dims[1:]
    )


def build_resnet():

    blocks = [

        nn.Sequential(

            nn.Linear(
                INPUT_DIM,
                128
            ),

            nn.ReLU()
        ),

        ResidualBlock(
            128,
            128
        ),

        ResidualBlock(
            128,
            96
        ),

        ResidualBlock(
            96,
            64
        ),

        ResidualBlock(
            64,
            48
        ),

        ResidualBlock(
            48,
            32
        ),

        ResidualBlock(
            32,
            16
        )
    ]

    dims = [
        128,
        128,
        96,
        64,
        48,
        32,
        16
    ]

    classifier = nn.Linear(
        16,
        1
    )

    return (
        blocks,
        classifier,
        dims
    )


def build_cnn():

    dims = [
        INPUT_DIM,
        128,
        96,
        64,
        48,
        32,
        16
    ]

    blocks = []

    for i in range(
        len(dims) - 1
    ):

        blocks.append(

            nn.Sequential(

                nn.Linear(
                    dims[i],
                    dims[i + 1]
                ),

                nn.ReLU()
            )
        )

    classifier = nn.Linear(
        16,
        1
    )

    return (
        blocks,
        classifier,
        dims[1:]
    )


def build_mobilenet():

    blocks = [

        nn.Sequential(

            nn.Linear(
                INPUT_DIM,
                128
            ),

            nn.ReLU()
        ),

        DepthwiseSeparableBlock(
            128,
            96
        ),

        DepthwiseSeparableBlock(
            96,
            64
        ),

        DepthwiseSeparableBlock(
            64,
            48
        ),

        DepthwiseSeparableBlock(
            48,
            32
        ),

        DepthwiseSeparableBlock(
            32,
            16
        )
    ]

    dims = [
        128,
        96,
        64,
        48,
        32,
        16
    ]

    classifier = nn.Linear(
        16,
        1
    )

    return (
        blocks,
        classifier,
        dims
    )


def build_efficientnet():

    blocks = [

        nn.Sequential(

            nn.Linear(
                INPUT_DIM,
                128
            ),

            nn.SiLU()
        ),

        MBConvTabular(
            128,
            96
        ),

        MBConvTabular(
            96,
            64
        ),

        MBConvTabular(
            64,
            48
        ),

        MBConvTabular(
            48,
            32
        ),

        MBConvTabular(
            32,
            16
        )
    ]

    dims = [
        128,
        96,
        64,
        48,
        32,
        16
    ]

    classifier = nn.Linear(
        16,
        1
    )

    return (
        blocks,
        classifier,
        dims
    )


def choose_nhead(
    dim
):

    for h in [
        8,
        4,
        2,
        1
    ]:

        if (
            dim % h
            ==
            0
        ):

            return h


def build_transformer():

    dims = [
        128,
        96,
        64,
        48,
        32,
        16
    ]

    blocks = [

        nn.Sequential(

            nn.Linear(
                INPUT_DIM,
                128
            ),

            nn.GELU()
        )
    ]

    transitions = [
        (128, 96),
        (96, 64),
        (64, 48),
        (48, 32),
        (32, 16)
    ]

    for (
        in_dim,
        out_dim
    ) in transitions:

        blocks.append(

            nn.Sequential(

                TransformerFeatureBlock(

                    in_dim,

                    choose_nhead(
                        in_dim
                    )
                ),

                nn.Linear(
                    in_dim,
                    out_dim
                ),

                nn.GELU()
            )
        )

    classifier = nn.Linear(
        16,
        1
    )

    return (
        blocks,
        classifier,
        dims
    )


ARCHITECTURES = {

    "MLP":
        build_mlp,

    "ResNet":
        build_resnet,

    "CNN":
        build_cnn,

    "MobileNet":
        build_mobilenet,

    "EfficientNet":
        build_efficientnet,

    "Transformer":
        build_transformer
}


# =============================================================================
# 18. SPLIT NETWORK
# =============================================================================

class SplitNetwork(nn.Module):

    def __init__(
        self,
        blocks,
        classifier,
        cut
    ):

        super().__init__()

        self.client = nn.Sequential(
            *blocks[:cut]
        )

        self.server = nn.Sequential(
            *blocks[cut:]
        )

        self.classifier = classifier


    def forward(
        self,
        x
    ):

        smashed = self.client(
            x
        )

        server_output = self.server(
            smashed
        )

        logits = self.classifier(
            server_output
        )

        return logits.squeeze(
            -1
        )


# =============================================================================
# 19. RESOURCE FUNCTIONS
# =============================================================================

def count_parameters(
    module
):

    return sum(

        p.numel()

        for p
        in module.parameters()
    )


def module_flops(
    module
):

    total = 0.0

    for m in module.modules():

        if isinstance(
            m,
            nn.Linear
        ):

            total += (

                2
                *
                m.in_features
                *
                m.out_features
            )

        elif isinstance(
            m,
            nn.Conv1d
        ):

            total += (

                2
                *
                m.out_channels
                *
                (
                    m.in_channels
                    /
                    m.groups
                )
                *
                m.kernel_size[0]
            )

        elif isinstance(
            m,
            nn.MultiheadAttention
        ):

            d = (
                m.embed_dim
            )

            total += (
                8 * d * d
            )

    return float(
        total
    )


def build_split_model(
    builder,
    cut
):

    (
        blocks,
        classifier,
        dims
    ) = builder()

    model = SplitNetwork(

        blocks,
        classifier,
        cut
    )

    return (
        model,
        dims
    )


# =============================================================================
# 20. TRAIN + EVALUATE ONE SPLIT
# =============================================================================

def evaluate_split(

    architecture_name,
    builder,
    cut
):

    random.seed(SEED)
    np.random.seed(SEED)
    torch.manual_seed(SEED)

    (
        model,
        dims
    ) = build_split_model(
        builder,
        cut
    )

    model = model.to(
        DEVICE
    )

    generator = torch.Generator()

    generator.manual_seed(
        SEED
    )

    train_loader = DataLoader(

        train_dataset,

        batch_size=TRAIN_BATCH_SIZE,

        shuffle=True,

        generator=generator
    )

    test_loader = DataLoader(

        test_dataset,

        batch_size=TEST_BATCH_SIZE,

        shuffle=False
    )

    optimizer = torch.optim.Adam(

        model.parameters(),

        lr=LEARNING_RATE
    )

    criterion = nn.BCEWithLogitsLoss()


    # -------------------------------------------------------------------------
    # TRAIN
    # -------------------------------------------------------------------------

    model.train()

    start_time = time.perf_counter()

    for epoch in range(
        EPOCHS_PER_SPLIT
    ):

        for xb, yb in train_loader:

            xb = xb.to(
                DEVICE
            )

            yb = yb.to(
                DEVICE
            )

            optimizer.zero_grad()

            logits = model(
                xb
            )

            loss = criterion(
                logits,
                yb
            )

            loss.backward()

            optimizer.step()

    latency = (
        time.perf_counter()
        -
        start_time
    )


    # -------------------------------------------------------------------------
    # TEST
    # -------------------------------------------------------------------------

    model.eval()

    probabilities = []
    labels = []

    with torch.no_grad():

        for xb, yb in test_loader:

            xb = xb.to(
                DEVICE
            )

            logits = model(
                xb
            )

            probs = torch.sigmoid(
                logits
            )

            probabilities.extend(

                probs.cpu()
                .numpy()
                .tolist()
            )

            labels.extend(

                yb.numpy()
                .tolist()
            )

    probabilities = np.asarray(
        probabilities
    )

    labels = np.asarray(
        labels,
        dtype=int
    )

    predictions = (
        probabilities
        >= 0.5
    ).astype(int)

    accuracy = accuracy_score(
        labels,
        predictions
    )

    precision = precision_score(
        labels,
        predictions,
        zero_division=0
    )

    recall = recall_score(
        labels,
        predictions,
        zero_division=0
    )

    f1 = f1_score(
        labels,
        predictions,
        zero_division=0
    )

    try:

        auc = roc_auc_score(
            labels,
            probabilities
        )

    except Exception:

        auc = np.nan


    # -------------------------------------------------------------------------
    # RESOURCE PROFILE
    # -------------------------------------------------------------------------

    activation_dim = (
        dims[
            cut - 1
        ]
    )

    communication_bytes = (

        2
        *
        TRAIN_BATCH_SIZE
        *
        activation_dim
        *
        4
    )

    client_flops = module_flops(
        model.client
    )

    server_flops = (

        module_flops(
            model.server
        )

        +

        module_flops(
            model.classifier
        )
    )

    client_params = count_parameters(
        model.client
    )

    server_params = (

        count_parameters(
            model.server
        )

        +

        count_parameters(
            model.classifier
        )
    )

    return {

        "dataset":
            DATASET_NAME,

        "architecture":
            architecture_name,

        "cut":
            int(cut),

        "activation_dim":
            int(activation_dim),

        "accuracy":
            float(accuracy),

        "precision":
            float(precision),

        "recall":
            float(recall),

        "f1":
            float(f1),

        "auc":
            float(auc),

        "communication_bytes":
            float(
                communication_bytes
            ),

        "client_flops":
            float(
                client_flops
            ),

        "server_flops":
            float(
                server_flops
            ),

        "client_params":
            float(
                client_params
            ),

        "server_params":
            float(
                server_params
            ),

        "latency":
            float(
                latency
            )
    }


# =============================================================================
# 21. NORMALIZATION + DEPLOYMENT REWARD
# =============================================================================

def minmax(
    values
):

    values = np.asarray(
        values,
        dtype=float
    )

    minimum = values.min()
    maximum = values.max()

    if np.isclose(
        minimum,
        maximum
    ):

        return np.zeros_like(
            values
        )

    return (

        values
        -
        minimum

    ) / (

        maximum
        -
        minimum
    )


def calculate_rewards(

    df,
    beta=DEFAULT_BETA
):

    df = df.copy()

    comm_norm = minmax(

        df[
            "communication_bytes"
        ].values
    )

    latency_norm = minmax(

        df[
            "latency"
        ].values
    )

    flops_norm = minmax(

        df[
            "client_flops"
        ].values
    )

    df["reward"] = (

        ALPHA
        *
        df["f1"].values

        -

        beta
        *
        comm_norm

        -

        GAMMA
        *
        latency_norm

        -

        DELTA
        *
        flops_norm
    )

    return df


# =============================================================================
# 22. RAST
#
# Same convention as previous runs:
# retain the three lowest-communication candidates.
# =============================================================================

def get_rast_cuts(
    results_df
):

    feasible = (

        results_df

        .sort_values(
            "communication_bytes",
            ascending=True
        )

        .head(3)
    )

    return sorted(

        feasible[
            "cut"
        ]
        .astype(int)
        .tolist()
    )


# =============================================================================
# 23. DA-UCB
# =============================================================================

def run_ucb(

    candidate_cuts,
    cut_results,

    n_rounds=N_ROUNDS,

    c=DEFAULT_UCB_C
):

    counts = {

        cut: 0

        for cut in candidate_cuts
    }

    means = {

        cut: 0.0

        for cut in candidate_cuts
    }

    history = []

    for t in range(
        1,
        n_rounds + 1
    ):

        unvisited = [

            cut

            for cut in candidate_cuts

            if counts[cut] == 0
        ]

        if unvisited:

            selected_cut = (
                unvisited[0]
            )

        else:

            scores = {}

            for cut in candidate_cuts:

                exploitation = (
                    means[cut]
                )

                exploration = (

                    c
                    *
                    np.sqrt(

                        np.log(t)
                        /
                        counts[cut]
                    )
                )

                scores[cut] = (

                    exploitation
                    +
                    exploration
                )

            selected_cut = max(

                scores,

                key=scores.get
            )

        reward = (
            cut_results[
                selected_cut
            ]["reward"]
        )

        counts[
            selected_cut
        ] += 1

        n = counts[
            selected_cut
        ]

        means[
            selected_cut
        ] += (

            reward
            -
            means[
                selected_cut
            ]

        ) / n

        history.append({

            "round":
                t,

            "cut":
                int(
                    selected_cut
                ),

            "reward":
                float(
                    reward
                )
        })

    history = pd.DataFrame(
        history
    )

    history[
        "best_reward"
    ] = (

        history[
            "reward"
        ]
        .cummax()
    )

    return history


# =============================================================================
# 24. RANDOM SEARCH
# =============================================================================

def run_random_search(

    candidate_cuts,
    cut_results,

    n_rounds=N_ROUNDS,

    seed=SEED
):

    rng = np.random.default_rng(
        seed
    )

    history = []

    best = -np.inf

    for t in range(
        1,
        n_rounds + 1
    ):

        cut = int(

            rng.choice(
                candidate_cuts
            )
        )

        reward = (
            cut_results[
                cut
            ]["reward"]
        )

        best = max(
            best,
            reward
        )

        history.append({

            "round":
                t,

            "cut":
                cut,

            "reward":
                float(
                    reward
                ),

            "best_reward":
                float(
                    best
                )
        })

    return pd.DataFrame(
        history
    )


# =============================================================================
# 25. EXHAUSTIVE SEARCH
# =============================================================================

def run_exhaustive(

    candidate_cuts,
    cut_results
):

    history = []

    best = -np.inf

    for (
        t,
        cut
    ) in enumerate(

        candidate_cuts,

        start=1
    ):

        reward = (
            cut_results[
                cut
            ]["reward"]
        )

        best = max(
            best,
            reward
        )

        history.append({

            "round":
                t,

            "cut":
                int(cut),

            "reward":
                float(
                    reward
                ),

            "best_reward":
                float(
                    best
                )
        })

    return pd.DataFrame(
        history
    )


# =============================================================================
# 26. FIRST ROUND REACHING GLOBAL OPTIMUM
# =============================================================================

def first_optimal_round(

    history,
    optimum
):

    matches = history[

        np.isclose(

            history[
                "best_reward"
            ],

            optimum,

            atol=1e-8
        )
    ]

    if len(
        matches
    ) == 0:

        return np.nan

    return int(

        matches.iloc[0][
            "round"
        ]
    )


# =============================================================================
# 27. FIVE SEARCH CONFIGURATIONS
# =============================================================================

def run_search_suite(

    architecture_name,
    results_df
):

    ALL_CUTS = (

        results_df[
            "cut"
        ]
        .astype(int)
        .tolist()
    )

    RAST_CUTS = get_rast_cuts(
        results_df
    )

    CUT_RESULTS = {

        int(row["cut"]):
            row.to_dict()

        for _, row
        in results_df.iterrows()
    }


    cabasl = run_ucb(

        RAST_CUTS,
        CUT_RESULTS,

        c=DEFAULT_UCB_C
    )


    no_rast = run_ucb(

        ALL_CUTS,
        CUT_RESULTS,

        c=DEFAULT_UCB_C
    )


    rast_random = run_random_search(

        RAST_CUTS,
        CUT_RESULTS
    )


    random_search = run_random_search(

        ALL_CUTS,
        CUT_RESULTS
    )


    exhaustive = run_exhaustive(

        ALL_CUTS,
        CUT_RESULTS
    )


    histories = {

        "CA-BASL":
            cabasl,

        "DA-UCB without RAST":
            no_rast,

        "RAST + Random":
            rast_random,

        "Random Search":
            random_search,

        "Exhaustive Search":
            exhaustive
    }


    optimal_row = (

        results_df

        .loc[

            results_df[
                "reward"
            ]
            .idxmax()
        ]
    )


    optimal_cut = int(
        optimal_row[
            "cut"
        ]
    )

    optimal_reward = float(
        optimal_row[
            "reward"
        ]
    )


    print("\n" + "=" * 90)

    print(
        architecture_name,
        "GLOBAL OPTIMUM"
    )

    print("=" * 90)

    print(
        "Optimal cut    :",
        "S" + str(
            optimal_cut
        )
    )

    print(
        "Optimal reward :",
        optimal_reward
    )

    print(
        "RAST cuts      :",
        RAST_CUTS
    )


    for (
        method,
        history
    ) in histories.items():

        print(
            "\n",
            architecture_name,
            "--",
            method
        )

        print(
            history.to_string(
                index=False
            )
        )


    return {

        "all_cuts":
            ALL_CUTS,

        "rast_cuts":
            RAST_CUTS,

        "cut_results":
            CUT_RESULTS,

        "histories":
            histories,

        "optimal_cut":
            optimal_cut,

        "optimal_reward":
            optimal_reward
    }


# =============================================================================
# 28. c-SENSITIVITY
# =============================================================================

def run_c_sensitivity(

    architecture_name,
    search_data
):

    rast_cuts = (
        search_data[
            "rast_cuts"
        ]
    )

    cut_results = (
        search_data[
            "cut_results"
        ]
    )

    rows = []
    histories = {}


    for c in C_VALUES:

        history = run_ucb(

            rast_cuts,
            cut_results,

            c=c
        )

        histories[c] = history

        best_reward = (
            history[
                "reward"
            ].max()
        )

        best_rows = history[

            np.isclose(

                history[
                    "reward"
                ],

                best_reward,

                atol=1e-12
            )
        ]

        best_cut = int(

            best_rows
            .iloc[0][
                "cut"
            ]
        )

        result = (
            cut_results[
                best_cut
            ]
        )

        rows.append({

            "dataset":
                DATASET_NAME,

            "backbone":
                architecture_name,

            "c":
                float(c),

            "best_cut":
                best_cut,

            "f1":
                result[
                    "f1"
                ],

            "communication_mb":
                (
                    result[
                        "communication_bytes"
                    ]
                    /
                    1e6
                ),

            "latency":
                result[
                    "latency"
                ],

            "reward":
                result[
                    "reward"
                ],

            "unique_splits":
                int(
                    history[
                        "cut"
                    ].nunique()
                )
        })


    return (

        pd.DataFrame(
            rows
        ),

        histories
    )


# =============================================================================
# 29. beta-SENSITIVITY
# =============================================================================

def run_beta_sensitivity(

    architecture_name,
    raw_results_df
):

    rows = []
    histories = {}

    RAST_CUTS = get_rast_cuts(
        raw_results_df
    )


    for beta in BETA_VALUES:

        beta_df = calculate_rewards(

            raw_results_df,

            beta=beta
        )

        CUT_RESULTS = {

            int(row["cut"]):
                row.to_dict()

            for _, row
            in beta_df.iterrows()
        }

        history = run_ucb(

            RAST_CUTS,
            CUT_RESULTS,

            c=DEFAULT_UCB_C
        )

        histories[
            beta
        ] = history

        best_reward = (
            history[
                "reward"
            ].max()
        )

        best_rows = history[

            np.isclose(

                history[
                    "reward"
                ],

                best_reward,

                atol=1e-12
            )
        ]

        best_cut = int(

            best_rows
            .iloc[0][
                "cut"
            ]
        )

        result = (
            CUT_RESULTS[
                best_cut
            ]
        )

        rows.append({

            "dataset":
                DATASET_NAME,

            "backbone":
                architecture_name,

            "beta":
                float(
                    beta
                ),

            "selected_cut":
                best_cut,

            "f1":
                result[
                    "f1"
                ],

            "communication_mb":
                (
                    result[
                        "communication_bytes"
                    ]
                    /
                    1e6
                ),

            "client_flops":
                result[
                    "client_flops"
                ],

            "latency":
                result[
                    "latency"
                ],

            "reward":
                result[
                    "reward"
                ]
        })


    return (

        pd.DataFrame(
            rows
        ),

        histories
    )


# =============================================================================
# 30. RUN COMPLETE EXPERIMENT FOR ONE ARCHITECTURE
# =============================================================================

def run_complete_architecture(

    architecture_name,
    builder
):

    print(
        "\n\n"
        +
        "#" * 100
    )

    print(
        "#",
        architecture_name
    )

    print(
        "#" * 100
    )


    (
        blocks,
        classifier,
        dims
    ) = builder()

    N_CUTS = len(
        blocks
    )

    split_results = []


    for cut in range(
        1,
        N_CUTS + 1
    ):

        print(
            "\nEvaluating",
            architecture_name,
            "split S"
            + str(cut)
        )

        result = evaluate_split(

            architecture_name,
            builder,
            cut
        )

        split_results.append(
            result
        )

        print(
            result
        )


    raw_df = pd.DataFrame(
        split_results
    )


    reward_df = calculate_rewards(

        raw_df,

        beta=DEFAULT_BETA
    )


    print("\n" + "=" * 90)

    print(
        architecture_name,
        "PER-SPLIT RESULTS"
    )

    print("=" * 90)

    print(
        reward_df.to_string(
            index=False
        )
    )


    search_data = run_search_suite(

        architecture_name,

        reward_df
    )


