# =============================================================================
# CA-BASL: ADAPTSFL-STYLE RESOURCE ROBUSTNESS EXPERIMENTS
#
# Dataset:
#   NSL-KDD
#
# Representative backbones:
#   MLP
#   ResNet
#
# Experiments:
#   Fig. X -- Effect of Client Compute Constraints
#   Fig. Y -- Effect of Communication Constraints
#   Fig. Z -- Robustness to Resource-Profile Uncertainty
#   Fig. W -- Search-Space Scalability
#
# IMPORTANT:
#   - NO neural-network retraining is performed.
#   - Existing experimentally measured split profiles are reused.
#   - Compute and communication delays are SIMULATED deployment quantities.
#   - Colab wall-clock latency is NOT treated as edge deployment latency.
#
# =============================================================================


