# =============================================================================
# 3. HELPER FUNCTIONS
# =============================================================================

def minmax(x):

    x = np.asarray(
        x,
        dtype=float
    )

    lo = np.min(x)
    hi = np.max(x)

    if np.isclose(
        lo,
        hi
    ):
        return np.zeros_like(x)

    return (
        x - lo
    ) / (
        hi - lo
    )


def deployment_profile(
    df,
    compute_gflops,
    bandwidth_mbps
):
    """
    Convert measured FLOPs / bytes into simulated deployment delay.

    client_flops is per sample.
    Therefore multiply by batch size.

    communication bytes already correspond to a batch.
    """

    out = df.copy()

    compute_ops_batch = (
        out["client_flops"].values
        *
        BATCH_SIZE
    )

    out["compute_delay_s"] = (
        compute_ops_batch
        /
        (
            compute_gflops
            *
            1e9
        )
    )

    out["comm_delay_s"] = (
        out["comm_bytes"].values
        *
        8.0
        /
        (
            bandwidth_mbps
            *
            1e6
        )
    )

    out["deployment_delay_s"] = (
        out["compute_delay_s"]
        +
        out["comm_delay_s"]
    )

    return out


def calculate_dynamic_reward(
    profile_df
):
    """
    Deployment reward evaluated under current simulated resources.

    F1                 -> benefit
    communication      -> communication penalty
    deployment delay   -> resource-dependent delay penalty
    client FLOPs       -> edge workload penalty
    """

    df = profile_df.copy()

    comm_norm = minmax(
        df["comm_bytes"]
    )

    delay_norm = minmax(
        df["deployment_delay_s"]
    )

    client_norm = minmax(
        df["client_flops"]
    )

    df["reward"] = (
        ALPHA * df["f1"].values
        -
        BETA * comm_norm
        -
        GAMMA * delay_norm
        -
        DELTA * client_norm
    )

    return df


def run_ucb(
    candidate_df,
    n_rounds=N_ROUNDS,
    c=UCB_C
):

    candidate_df = (
        candidate_df
        .sort_values("cut")
        .reset_index(drop=True)
    )

    candidates = (
        candidate_df["cut"]
        .astype(int)
        .tolist()
    )

    reward_map = dict(
        zip(
            candidate_df["cut"],
            candidate_df["reward"]
        )
    )

    counts = {
        cut: 0
        for cut in candidates
    }

    means = {
        cut: 0.0
        for cut in candidates
    }

    history = []

    for t in range(
        1,
        n_rounds + 1
    ):

        unvisited = [
            cut
            for cut in candidates
            if counts[cut] == 0
        ]

        if unvisited:

            selected = unvisited[0]

        else:

            scores = {}

            for cut in candidates:

                exploitation = means[cut]

                exploration = (
                    c
                    *
                    np.sqrt(
                        np.log(t)
                        /
                        counts[cut]
                    )
                )

                scores[cut] = (
                    exploitation
                    +
                    exploration
                )

            selected = max(
                scores,
                key=scores.get
            )

        reward = float(
            reward_map[selected]
        )

        counts[selected] += 1

        n = counts[selected]

        means[selected] += (
            reward
            -
            means[selected]
        ) / n

        history.append({
            "round": t,
            "cut": selected,
            "reward": reward
        })

    history = pd.DataFrame(
        history
    )

    history["best_reward"] = (
        history["reward"]
        .cummax()
    )

    return history


def select_cabasl(
    profile_df,
    feasible_mask
):
    """
    Run CA-BASL over only the resource-feasible candidate set.

    Returns:
        selected row,
        history,
        feasible dataframe
    """

    feasible_df = (
        profile_df[
            feasible_mask
        ]
        .copy()
    )

    # Avoid empty candidate set.
    # If no split satisfies the resource condition,
    # choose the least violating split as a fallback indicator.
    if len(feasible_df) == 0:

        return None, None, feasible_df

    history = run_ucb(
        feasible_df
    )

    best_reward = (
        history["reward"]
        .max()
    )

    best_cut = int(
        history.loc[
            history["reward"].idxmax(),
            "cut"
        ]
    )

    selected = (
        feasible_df[
            feasible_df["cut"]
            ==
            best_cut
        ]
        .iloc[0]
    )

    return (
        selected,
        history,
        feasible_df
    )


