# =============================================================================
# 9. FIG. Z -- RESOURCE-PROFILE UNCERTAINTY
# =============================================================================
#
# The TRUE deployment environment is fixed.
#
# RAST sees noisy estimates:
#
#     C_hat = C_true * (1 + epsilon_C)
#     B_hat = B_true * (1 + epsilon_B)
#
# epsilon ~ Normal(0, sigma)
#
# CA-BASL selects using estimated resources.
#
# We then evaluate:
#
#   1. split-selection stability
#   2. true feasibility violations
#   3. reward degradation
#   4. feasible-candidate count
#
# =============================================================================

UNCERTAINTY_LEVELS = [
    0.00,
    0.05,
    0.10,
    0.20,
    0.30,
    0.40
]

N_MONTE_CARLO = 50


uncertainty_rows = []


for backbone, raw_df in BACKBONES.items():

    # -------------------------------------------------------------------------
    # True profile
    # -------------------------------------------------------------------------

    true_profile = deployment_profile(

        raw_df,

        compute_gflops=
            BASE_COMPUTE_GFLOPS,

        bandwidth_mbps=
            BASE_BANDWIDTH_MBPS
    )

    true_profile = calculate_dynamic_reward(
        true_profile
    )

    true_feasible = (

        (
            true_profile[
                "compute_delay_s"
            ]
            <=
            COMPUTE_DELAY_BUDGET
        )

        &

        (
            true_profile[
                "comm_delay_s"
            ]
            <=
            COMM_DELAY_BUDGET
        )
    )

    (
        perfect_selected,
        perfect_history,
        perfect_feasible_df
    ) = select_cabasl(

        true_profile,

        true_feasible
    )


    if perfect_selected is None:

        raise RuntimeError(
            f"No feasible base candidate for {backbone}. "
            "Increase the resource budgets."
        )


    perfect_cut = int(
        perfect_selected["cut"]
    )

    perfect_reward = float(
        perfect_selected["reward"]
    )


    # -------------------------------------------------------------------------
    # Noise levels
    # -------------------------------------------------------------------------

    for sigma in UNCERTAINTY_LEVELS:

        stable_count = 0

        violation_count = 0

        reward_degradations = []

        feasible_counts = []


        for mc in range(
            N_MONTE_CARLO
        ):

            local_rng = np.random.default_rng(

                SEED
                +
                mc
                +
                int(
                    sigma * 10000
                )
                +
                (
                    100000
                    if backbone == "ResNet"
                    else 0
                )
            )


            compute_error = (
                local_rng.normal(
                    0.0,
                    sigma
                )
            )

            bandwidth_error = (
                local_rng.normal(
                    0.0,
                    sigma
                )
            )


            estimated_compute = max(

                BASE_COMPUTE_GFLOPS
                *
                (
                    1.0
                    +
                    compute_error
                ),

                1e-4
            )


            estimated_bandwidth = max(

                BASE_BANDWIDTH_MBPS
                *
                (
                    1.0
                    +
                    bandwidth_error
                ),

                1e-4
            )


            # -------------------------------------------------------------
            # RAST operates on ESTIMATED resource profile
            # -------------------------------------------------------------

            estimated_profile = deployment_profile(

                raw_df,

                compute_gflops=
                    estimated_compute,

                bandwidth_mbps=
                    estimated_bandwidth
            )

            estimated_profile = calculate_dynamic_reward(
                estimated_profile
            )


            estimated_feasible = (

                (
                    estimated_profile[
                        "compute_delay_s"
                    ]
                    <=
                    COMPUTE_DELAY_BUDGET
                )

                &

                (
                    estimated_profile[
                        "comm_delay_s"
                    ]
                    <=
                    COMM_DELAY_BUDGET
                )
            )


            (
                noisy_selected,
                noisy_history,
                noisy_feasible_df
            ) = select_cabasl(

                estimated_profile,

                estimated_feasible
            )


            feasible_counts.append(
                len(
                    noisy_feasible_df
                )
            )


            if noisy_selected is None:

                violation_count += 1

                reward_degradations.append(
                    perfect_reward
                )

                continue


            noisy_cut = int(
                noisy_selected[
                    "cut"
                ]
            )


            if noisy_cut == perfect_cut:

                stable_count += 1


            # -------------------------------------------------------------
            # Evaluate selected split under TRUE resource profile
            # -------------------------------------------------------------

            true_selected = (

                true_profile[
                    true_profile["cut"]
                    ==
                    noisy_cut
                ]
                .iloc[0]
            )


            truly_feasible = (

                (
                    true_selected[
                        "compute_delay_s"
                    ]
                    <=
                    COMPUTE_DELAY_BUDGET
                )

                and

                (
                    true_selected[
                        "comm_delay_s"
                    ]
                    <=
                    COMM_DELAY_BUDGET
                )
            )


            if not truly_feasible:

                violation_count += 1


            true_reward_selected = float(

                true_selected[
                    "reward"
                ]
            )


            degradation = max(

                0.0,

                perfect_reward
                -
                true_reward_selected
            )


            reward_degradations.append(
                degradation
            )


        uncertainty_rows.append({

            "backbone":
                backbone,

            "sigma":
                sigma,

            "split_stability_percent":
                (
                    stable_count
                    /
                    N_MONTE_CARLO
                    *
                    100
                ),

            "violation_rate_percent":
                (
                    violation_count
                    /
                    N_MONTE_CARLO
                    *
                    100
                ),

            "mean_reward_degradation":
                np.mean(
                    reward_degradations
                ),

            "std_reward_degradation":
                np.std(
                    reward_degradations
                ),

            "mean_feasible_candidates":
                np.mean(
                    feasible_counts
                ),

            "perfect_cut":
                perfect_cut,

            "perfect_reward":
                perfect_reward
        })


UNCERTAINTY_DF = pd.DataFrame(
    uncertainty_rows
)


print("\n" + "=" * 100)

print(
    "FIG. Z -- RESOURCE UNCERTAINTY RESULTS"
)

print("=" * 100)

