# =============================================================================
# 11. FIG. W -- SEARCH-SPACE SCALABILITY
# =============================================================================
#
# This is the CA-BASL-specific counterpart to system scalability.
#
# We DO NOT invent a fake multi-client experiment.
#
# Existing NSL-KDD architecture results are used.
#
# Delta R = exhaustive reward - CA-BASL reward
