# =============================================================================
# CA-BASL — COMMUNICATION-RESOURCE ADAPTATION
# CORRECTED VERSION: FIXED/GLOBAL NORMALIZATION
#
# No model retraining.
# Uses the existing NSL-KDD MLP + ResNet split results.
#
# Produces:
#   (a) RAST-feasible candidate space
#   (b) Selected split
#   (c) Estimated communication delay
#   (d) Deployment reward
#
# IMPORTANT FIX:
# Communication delay is normalized ONCE over a fixed reference range
# covering all architectures, splits, and bandwidth conditions.
# =============================================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


# =============================================================================
# 1. EXPERIMENT SETTINGS
# =============================================================================

BANDWIDTHS_MBPS = np.array([
    1, 2, 5, 10, 25, 50, 100
], dtype=float)

# Maximum acceptable communication delay
MAX_COMM_DELAY_S = 0.30

# Reward weights
# Keep the same deployment-aware structure used in the earlier experiment.
ALPHA_F1 = 1.00
BETA_COMM = 0.25
GAMMA_DELAY = 0.15
DELTA_FLOPS = 0.10


# =============================================================================
# 2. EXISTING NSL-KDD MLP RESULTS
# =============================================================================
#
# These are NOT retrained.
# They are the existing per-split results.
#
# comm = communication bytes / batch
# =============================================================================

MLP_RESULTS = {
    1: {
        "f1": 0.777228,
        "comm": 524288.0,
    },
    2: {
        "f1": 0.770322,
        "comm": 393216.0,
    },
    3: {
        "f1": 0.766092,
        "comm": 262144.0,
    },
    4: {
        "f1": 0.780358,
        "comm": 196608.0,
    },
    5: {
        "f1": 0.796594,
        "comm": 131072.0,
    },
    6: {
        "f1": 0.716506,
        "comm": 65536.0,
    }
}


# =============================================================================
# 3. EXISTING NSL-KDD RESNET RESULTS
# =============================================================================

RESNET_RESULTS = {
    1: {
        "f1": 0.7858697161905643,
        "comm": 524288.0,
        "client_flops": 10496.0,
    },
    2: {
        "f1": 0.7858697161905643,
        "comm": 524288.0,
        "client_flops": 76032.0,
    },
    3: {
        "f1": 0.7858697161905643,
        "comm": 393216.0,
        "client_flops": 143616.0,
    },
    4: {
        "f1": 0.7858697161905643,
        "comm": 262144.0,
        "client_flops": 176384.0,
    },
    5: {
        "f1": 0.7858697161905643,
        "comm": 196608.0,
        "client_flops": 193280.0,
    },
    6: {
        "f1": 0.7858697161905643,
        "comm": 131072.0,
        "client_flops": 201472.0,
    },
    7: {
        "f1": 0.7858697161905643,
        "comm": 65536.0,
        "client_flops": 204032.0,
    }
}


# =============================================================================
# 4. MLP CLIENT FLOPS
# =============================================================================
#
# If your original MLP resource-profile code contains different exact FLOP
# values, replace ONLY these values with those original values.
#
# These values preserve the increasing client-workload structure across cuts.
# =============================================================================

MLP_CLIENT_FLOPS = {
    1: 10752.0,
    2: 27136.0,
    3: 43520.0,
    4: 51712.0,
    5: 55808.0,
    6: 56832.0,
}

for cut in MLP_RESULTS:
    MLP_RESULTS[cut]["client_flops"] = MLP_CLIENT_FLOPS[cut]


# =============================================================================
# 5. UTILITY FUNCTIONS
# =============================================================================

def communication_delay_seconds(comm_bytes, bandwidth_mbps):
    """
    Transmission delay:

        delay = bits / bits_per_second

    bandwidth_mbps is interpreted as megabits/second.
    """

    bits = comm_bytes * 8.0
    bandwidth_bps = bandwidth_mbps * 1e6

    return bits / bandwidth_bps


def fixed_normalize(value, global_min, global_max):
    """
    Fixed normalization.

    The SAME min/max are used at every bandwidth.
    """

    if np.isclose(global_max, global_min):
        return 0.0

    return (value - global_min) / (global_max - global_min)


# =============================================================================
# 6. GLOBAL NORMALIZATION CONSTANTS
# =============================================================================
#
# THIS IS THE IMPORTANT CORRECTION.
#
# Previously:
#
#     delay_norm = minmax(df["deployment_delay_s"])
#
# was effectively recalculated separately for each bandwidth.
#
# Here we construct ALL possible delays first and determine ONE global
# normalization range.
# =============================================================================

ALL_MODELS = {
    "MLP": MLP_RESULTS,
    "ResNet": RESNET_RESULTS
}

all_delays = []
all_comm = []
all_flops = []

for model_name, results in ALL_MODELS.items():

    for cut, values in results.items():

        all_comm.append(values["comm"])
        all_flops.append(values["client_flops"])

        for bw in BANDWIDTHS_MBPS:

            delay = communication_delay_seconds(
                values["comm"],
                bw
            )

            all_delays.append(delay)


GLOBAL_DELAY_MIN = min(all_delays)
GLOBAL_DELAY_MAX = max(all_delays)

GLOBAL_COMM_MIN = min(all_comm)
GLOBAL_COMM_MAX = max(all_comm)

GLOBAL_FLOPS_MIN = min(all_flops)
GLOBAL_FLOPS_MAX = max(all_flops)


print("=" * 90)
print("FIXED GLOBAL NORMALIZATION")
print("=" * 90)

print(
    f"Delay range : "
    f"{GLOBAL_DELAY_MIN:.6f} -- "
    f"{GLOBAL_DELAY_MAX:.6f} s"
)

print(
    f"Comm range  : "
    f"{GLOBAL_COMM_MIN:.0f} -- "
    f"{GLOBAL_COMM_MAX:.0f} bytes"
)

print(
    f"FLOPs range : "
    f"{GLOBAL_FLOPS_MIN:.0f} -- "
    f"{GLOBAL_FLOPS_MAX:.0f}"
)


# =============================================================================
# 7. DEPLOYMENT REWARD
# =============================================================================

def calculate_reward(
    f1,
    comm_bytes,
    delay_seconds,
    client_flops
):

    comm_norm = fixed_normalize(
        comm_bytes,
        GLOBAL_COMM_MIN,
        GLOBAL_COMM_MAX
    )

    delay_norm = fixed_normalize(
        delay_seconds,
        GLOBAL_DELAY_MIN,
        GLOBAL_DELAY_MAX
    )

    flops_norm = fixed_normalize(
        client_flops,
        GLOBAL_FLOPS_MIN,
        GLOBAL_FLOPS_MAX
    )

    reward = (
        ALPHA_F1 * f1
        - BETA_COMM * comm_norm
        - GAMMA_DELAY * delay_norm
        - DELTA_FLOPS * flops_norm
    )

    return reward


# =============================================================================
# 8. RUN BANDWIDTH EXPERIMENT
# =============================================================================

def run_bandwidth_experiment(
    model_name,
    split_results
):

    rows = []

    for bandwidth in BANDWIDTHS_MBPS:

        candidates = []

        # ---------------------------------------------------------------------
        # Evaluate all candidate splits
        # ---------------------------------------------------------------------

        for cut, values in split_results.items():

            delay = communication_delay_seconds(
                values["comm"],
                bandwidth
            )

            feasible = (
                delay <= MAX_COMM_DELAY_S
            )

            reward = calculate_reward(
                f1=values["f1"],
                comm_bytes=values["comm"],
                delay_seconds=delay,
                client_flops=values["client_flops"]
            )

            candidates.append({
                "cut": cut,
                "f1": values["f1"],
                "comm": values["comm"],
                "client_flops": values["client_flops"],
                "delay": delay,
                "reward": reward,
                "feasible": feasible
            })

        candidate_df = pd.DataFrame(candidates)

        feasible_df = candidate_df[
            candidate_df["feasible"]
        ].copy()

        # ---------------------------------------------------------------------
        # RAST feasibility filtering
        # ---------------------------------------------------------------------

        n_feasible = len(feasible_df)

        if n_feasible == 0:

            # No feasible deployment under this bandwidth.
            selected_cut = np.nan
            selected_reward = np.nan
            selected_delay = np.nan
            selected_f1 = np.nan
            selected_comm = np.nan

        else:

            # -----------------------------------------------------------------
            # CA-BASL deployment choice
            #
            # Since the reward of every candidate is already known from the
            # completed split experiments, selecting the maximum reward here
            # represents the final deployment decision after RAST filtering.
            # -----------------------------------------------------------------

            best_idx = feasible_df["reward"].idxmax()

            best = feasible_df.loc[best_idx]

            selected_cut = int(best["cut"])
            selected_reward = best["reward"]
            selected_delay = best["delay"]
            selected_f1 = best["f1"]
            selected_comm = best["comm"]

        rows.append({
            "model": model_name,
            "bandwidth_mbps": bandwidth,
            "feasible_candidates": n_feasible,
            "selected_cut": selected_cut,
            "communication_delay_s": selected_delay,
            "f1": selected_f1,
            "communication_bytes": selected_comm,
            "reward": selected_reward
        })

    return pd.DataFrame(rows)


# =============================================================================
# 9. RUN MLP + RESNET
# =============================================================================

mlp_bandwidth = run_bandwidth_experiment(
    "MLP",
    MLP_RESULTS
)

resnet_bandwidth = run_bandwidth_experiment(
    "ResNet",
    RESNET_RESULTS
)

results = pd.concat(
    [
        mlp_bandwidth,
        resnet_bandwidth
    ],
    ignore_index=True
)


# =============================================================================
